def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    keyboard_patches = image_patch.find("keyboard")
    baby_patches = image_patch.find("baby")

    if not keyboard_patches or not baby_patches:
        return image_patch

    baby_min_y = min(p.lower for p in baby_patches)
    baby_max_x = max(p.right for p in baby_patches)

    reachable_area = []
    for key in keyboard_patches:
        if key.upper >= baby_min_y and key.left <= baby_max_x:
            reachable_area.append(key)

    if not reachable_area:
        return image_patch

    return max(reachable_area, key=lambda k: (k.upper - k.lower) * (k.right - k.left))

