    image_patch = ImagePatch(image)
    chair_patches = image_patch.find("chair")
    if not chair_patches:
        return image_patch

    # Sort chairs by their horizontal position
    chair_patches.sort(key=lambda p: p.left)

    # Find the first chair that is to the left of another chair
    for i in range(1, len(chair_patches)):
        if chair_patches[i].left < chair_patches[i-1].right:
            return chair_patches[i]

    # If no chair is to the left of another, return the first chair found
    return chair_patches[0]

