    image_patch = ImagePatch(image)
    sandwich_patches = image_patch.find("sandwich")
    if len(sandwich_patches) < 2:
        return image_patch

    sandwich_patches.sort(key=lambda s: s.compute_depth(), reverse=True)
    front_sandwich = sandwich_patches[0]
    back_sandwiches = sandwich_patches[1:]

    for back_sandwich in back_sandwiches:
        if front_sandwich.overlaps_with(back_sandwich.left, back_sandwich.lower, back_sandwich.right, back_sandwich.upper):
            return back_sandwich

    return front_sandwich

